// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';

// URL for test requests
// Every request below carries its own full /ghost/api/... path, so the client needs the
// site origin. Injected service URLs point at a specific API mount, so take their origin.
const URL_localhost = new URL(getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:2368")).origin;

test('testIntegration', async ({ request }) => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Cookie"] = process.env.SKYRAMP_TEST_TOKEN;
    }

    // Execute Request
    const endpoint1GetResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/ghost/api/admin/integrations/",
        method: "GET",
        headers: headers,
        queryParams: {"include": ["api_keys"]}
    });

    // Generated Assertions
    expect(endpoint1GetResponse.statusCode, 'status code').toBe(200);
    const contentApiKeys = (getResponseValue(endpoint1GetResponse, "integrations") || [])
        .flatMap((integration: {api_keys?: {type: string, secret: string}[]}) => integration.api_keys || [])
        .filter((apiKey: {type: string}) => apiKey.type === "content");
    expect(contentApiKeys.length, 'content api key count').toBeGreaterThan(0);

    // Declaration of variables
    const key_1: string = contentApiKeys[0].secret;
    expect(key_1, 'content api key').toMatch(/^[0-9a-f]{26}$/);

    // Execute Request
    const endpoint2GetResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/ghost/api/content/posts/",
        method: "GET",
        headers: headers,
        queryParams: {
            "key": [key_1],
            "limit": ["1"]
        }
    });

    // Generated Assertions
    expect(endpoint2GetResponse.statusCode, 'status code').toBe(200);
    expect(getValue(endpoint2GetResponse, "posts").length, 'posts length honours limit=1').toBe(1);
    expect(getResponseValue(endpoint2GetResponse, "posts.0.slug"), 'posts.0.slug').toMatch(/^[a-z0-9-]+$/);
    expect(getResponseValue(endpoint2GetResponse, "posts.1"), 'posts.1').toBeNull();
    expect(getResponseValue(endpoint2GetResponse, "errors"), 'errors').toBeNull();

    // The slug, id and title of the post the retired path must keep serving
    const browsedSlug: string = getResponseValue(endpoint2GetResponse, "posts.0.slug");
    const browsedId: string = getResponseValue(endpoint2GetResponse, "posts.0.id");
    const browsedTitle: string = getResponseValue(endpoint2GetResponse, "posts.0.title");

    const retiredUrl = `${URL_localhost}/ghost/api/content/posts/slug/${browsedSlug}/?key=${key_1}`;

    // Execute Request — the retired path, WITHOUT following the redirect
    const endpoint3GetNoFollowResponse = await request.get(retiredUrl, {maxRedirects: 0});

    // Generated Assertions
    expect(endpoint3GetNoFollowResponse.status(), 'status code').toBe(301);
    const redirectLocation = endpoint3GetNoFollowResponse.headers()['location'];
    expect(redirectLocation, 'location header').toBeTruthy();
    // Resolved against the request URL so an absolute or a relative Location both pass,
    // but the target must be the content API path, not a site-root path.
    const resolvedLocation = new URL(redirectLocation, retiredUrl);
    expect(resolvedLocation.pathname, 'location pathname').toBe(`/ghost/api/content/posts/by-slug/${browsedSlug}/`);
    expect(resolvedLocation.searchParams.get('key'), 'location preserves the key query param').toBe(key_1);

    // Execute Request — the retired path, FOLLOWING the redirect
    const endpoint3GetFollowed = await request.get(retiredUrl);
    const endpoint3GetResponse = {statusCode: endpoint3GetFollowed.status()};

    // Generated Assertions
    expect(endpoint3GetResponse.statusCode, 'status code').toBe(200);
    expect(endpoint3GetFollowed.headers()['content-type'], 'content type').toContain('application/json');
    const redirectedBody = await endpoint3GetFollowed.json();
    expect(redirectedBody.posts.length, 'posts length').toBe(1);
    expect(redirectedBody.posts[0].slug, 'posts.0.slug echoes the requested slug').toBe(browsedSlug);
    expect(redirectedBody.posts[0].id, 'posts.0.id').toBe(browsedId);
    expect(redirectedBody.posts[0].title, 'posts.0.title').toBe(browsedTitle);
    expect(redirectedBody.posts[1], 'posts.1').toBeUndefined();
    expect(redirectedBody.errors, 'errors').toBeUndefined();

    // Execute Request
    const endpoint3Get1Response = await client.sendRequest({
        url: URL_localhost,
        path: "/ghost/api/content/posts/slug/{slug}/",
        method: "GET",
        headers: headers,
        pathParams: {"slug": browsedSlug}
    });

    // Generated Assertions
    expect(endpoint3Get1Response.statusCode, 'status code').toBe(403);
    expect(getResponseValue(endpoint3Get1Response, "errors.0.message"), 'errors.0.message').toBe("Authorization failed");
    expect(getResponseValue(endpoint3Get1Response, "errors.0.type"), 'errors.0.type').toBe("NoPermissionError");
    expect(getResponseValue(endpoint3Get1Response, "errors.1"), 'errors.1').toBeNull();
    expect(getResponseValue(endpoint3Get1Response, "posts"), 'posts').toBeNull();

    // Execute Request
    const endpoint3Get2Response = await client.sendRequest({
        url: URL_localhost,
        path: "/ghost/api/content/posts/slug/{slug}/",
        method: "GET",
        headers: headers,
        pathParams: {"slug": browsedSlug},
        queryParams: {"key": ["deadbeefdeadbeefdeadbeef00"]}
    });

    // Generated Assertions
    expect(endpoint3Get2Response.statusCode, 'status code').toBe(401);
    expect(getResponseValue(endpoint3Get2Response, "errors.0.message"), 'errors.0.message').toBe("Unknown Content API Key");
    expect(getResponseValue(endpoint3Get2Response, "errors.0.type"), 'errors.0.type').toBe("UnauthorizedError");
    expect(getResponseValue(endpoint3Get2Response, "errors.0.code"), 'errors.0.code').toBe("UNKNOWN_CONTENT_API_KEY");
    expect(getResponseValue(endpoint3Get2Response, "errors.1"), 'errors.1').toBeNull();
    expect(getResponseValue(endpoint3Get2Response, "posts"), 'posts').toBeNull();

    // Execute Request — the redirect is path-level, so an unknown slug still redirects
    const unknownSlugUrl = `${URL_localhost}/ghost/api/content/posts/slug/no-such-post-xyz-9f21/?key=${key_1}`;
    const endpoint4GetResponse = await request.get(unknownSlugUrl, {maxRedirects: 0});

    // Generated Assertions
    expect(endpoint4GetResponse.status(), 'status code').toBe(301);
    const unknownSlugLocation = new URL(endpoint4GetResponse.headers()['location'], unknownSlugUrl);
    expect(unknownSlugLocation.pathname, 'location pathname').toBe('/ghost/api/content/posts/by-slug/no-such-post-xyz-9f21/');
    expect(unknownSlugLocation.searchParams.get('key'), 'location preserves the key query param').toBe(key_1);
});
